import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>AVIF, web'in en yeni görsel formatıdır. JPG'den çok daha küçüktür ama birçok uygulama onu açamaz.</p>\n<p>Modern sitelerden indirdiğiniz görseller AVIF olabilir. Form, e-posta ya da eski bir program dosyayı reddederse JPG'ye dönüştürmeniz gerekir.</p>\n<p>Bu kılavuz, AVIF'in ne olduğunu, uygulamaların neden reddettiğini ve kalite ile saydamlığı doğru yöneterek JPG'ye nasıl dönüştüreceğinizi anlatıyor.</p>\n<h2 id=\"what-is-avif\">AVIF nedir?</h2>\n<p>AVIF, AV1 video codec'ine dayanan bir görsel formatıdır. 2019'da tanıtıldı ve web'de hızla yayılıyor.</p>\n<p>AVIF'in gücü sıkıştırmadır. Aynı kalitede JPG'den yüzde 30-50 daha küçük dosyalar üretir.</p>\n<p>AVIF ayrıca HDR ve geniş renk gamını destekler. Fotoğraflar daha zengin renklerle saklanabilir.</p>\n<h2 id=\"why-websites-use-avif\">Modern siteler neden AVIF sunuyor?</h2>\n<p>Siteler hız ister ve AVIF hız verir. Daha küçük dosyalar, daha hızlı sayfalar demektir.</p>\n<p>Modern tarayıcılar AVIF'i destekler. Chrome, Firefox ve Safari AVIF gösterir; bu yüzden siteler onu güvenle sunar.</p>\n<p>Haber ve e-ticaret siteleri AVIF'i sever. Onlarca görseli olan sayfalarda toplam kazanç çok büyüktür.</p>\n<h2 id=\"why-apps-reject-avif\">Uygulamalar ve formlar AVIF'i neden reddediyor?</h2>\n<p>Uygulamalar formatları yavaş benimser. AVIF yeni olduğu için birçok program onu henüz tanımıyor.</p>\n<p>Formlar ve portallar genellikle yalnızca JPG ve PNG kabul eder. AVIF listede yoksa dosya geri döner.</p>\n<p>Eski işletim sistemleri de AVIF açamaz. Dosya, eski bir bilgisayarda kırık simge olarak görünür.</p>\n<h2 id=\"how-decoding-works\">Tarayıcıda AVIF çözme nasıl çalışır?</h2>\n<p>Tarayıcı, AVIF dosyasını açmak için yerleşik bir çözücü kullanır. Çözücü, sıkıştırılmış veriyi piksel haritasına çevirir.</p>\n<p>Modern tarayıcıların tamamında bu çözücü vardır. Eski tarayıcılarda yoktur; görsel açılmaz.</p>\n<p>Dönüştürücü, tarayıcının çözücüsünü kullanır. Tarayıcı AVIF açabiliyorsa dönüştürücü de dönüştürebilir.</p>\n<h2 id=\"quality-settings\">İşe yarayan kalite ayarları</h2>\n<p>Fotoğraflar için kaliteyi yüzde 85 civarında tutun. Bu seviyede fark gözle görülmez ve dosya hâlâ küçüktür.</p>\n<p>Metin içeren görseller için yüzde 90 kullanın. Yazılar keskin kalmalıdır; düşük kalite bulanıklık yapar.</p>\n<p>Kaliteyi düşürerek deneyin. Yüzde 80'den başlayın; fark görmüyorsanız daha da düşürün.</p>\n<h2 id=\"file-size-after\">JPG neden AVIF'ten daha büyük?</h2>\n<p>JPG daha eski ve daha az verimli bir formattır. Aynı görseli AVIF'ten daha fazla baytla saklar.</p>\n<p>Bir AVIF 200 KB ise JPG sürümü 400 KB olabilir. Bu fark normaldir; JPG'nin bedelidir.</p>\n<p>Boyut farkı, uyumluluğun karşılığıdır. JPG her yerde açılır; AVIF açılmaz.</p>\n<h2 id=\"transparency-handling\">AVIF dönüştürmede saydamlık</h2>\n<p>AVIF saydamlığı destekler ama JPG desteklemez. Saydam alanlar JPG'de bir arka plan rengiyle dolar.</p>\n<p>Dönüştürmeden önce arka plan rengini seçin. Beyaz genellikle doğrudur; koyu temalı görsellerde siyah daha iyi olabilir.</p>\n<p>Saydamlık önemliyse JPG yerine PNG'ye dönüştürün. PNG alfa kanalını korur; JPG koruyamaz.</p>\n<h2 id=\"hdr-and-colour\">HDR ve geniş renkli fotoğraflar</h2>\n<p>AVIF HDR fotoğrafları saklayabilir; JPG saklayamaz. Dönüştürmede HDR bilgisi kaybolur.</p>\n<p>Çoğu ekranda fark görülmez. Standart ekranlar HDR göstermez; bu yüzden kayıp pratikte önemsizdir.</p>\n<p>Profesyonel işlerde orijinal AVIF'i saklayın. HDR arşiv için önemlidir; JPG yalnızca paylaşım içindir.</p>\n<h2 id=\"batch-converting\">İndirilen AVIF'leri toplu dönüştürmek</h2>\n<p>Bir siteden indirdiğiniz onlarca AVIF'i tek tek dönüştürmek zaman kaybıdır. Tümünü aynı anda yükleyip toplu dönüştürün.</p>\n<p>Toplu dönüştürmede tüm dosyalar için aynı kalite ayarını kullanın. Tutarlılık, sonuçları öngörülebilir kılar.</p>\n<p>Dönüştürülen dosyaları ZIP olarak alın. Tek indirme, çok sayıda dosyayı düzenli tutar.</p>\n<h2 id=\"checking-quality\">İndirmeden önce kaliteyi kontrol etmek</h2>\n<p>Her zaman önizlemeyle karşılaştırın. Orijinal AVIF ile dönüştürülen JPG'yi yan yana açın.</p>\n<p>Yüzde 100 yakınlaştırmada inceleyin. Küçük resimde gizlenen kusurlar tam boyutta ortaya çıkar.</p>\n<p>Şüphede kalırsanız kaliteyi beş puan artırın. Birkaç KB fazladan boyut, bozuk bir fotoğraftan her zaman iyidir.</p>\n<h2 id=\"avif-vs-jpg-decision\">AVIF ne zaman korunmalı?</h2>\n<p>Web'de kalacak bir görselde AVIF'i koruyun. Hız kazancı gerçektir ve tarayıcılar destekler.</p>\n<p>Dosya tarayıcı dışına çıkacaksa JPG'ye dönüştürün. Form, e-posta ve eski programlar JPG ister.</p>\n<p>Arşiv için AVIF'i koruyun. En küçük ve en kaliteli sürüm, arşiv için idealdir.</p>\n<h2 id=\"common-problems\">Yaygın sorunlar ve çözümler</h2>\n<p>Tarayıcı AVIF açamıyorsa dönüştürücü de açamaz. Tarayıcıyı güncelleyin ya da modern bir tarayıcı kullanın.</p>\n<p>Saydam alanlar siyah görünüyorsa arka plan rengini kontrol edin. Beyaz seçmek genellikle sorunu çözer.</p>\n<p>Dönüştürülen JPG çok büyükse kaliteyi düşürün. Yüzde 80'den 75'e inmek genellikle görünür fark yaratmadan boyutu küçültür.</p>\n<h2 id=\"avif-from-news-sites\">Haber sitelerinden AVIF görselleri</h2>\n<p>Haber siteleri görselleri AVIF sunar. İndirdiğiniz haber fotoğrafı AVIF olabilir.</p>\n<p>Bu fotoğrafları sunumda kullanmadan önce JPG'ye dönüştürün. Sunum programları AVIF açmayabilir.</p>\n<p>Telif hakkına dikkat edin. Haber fotoğraflarını izinsiz kullanmak yasal sorun çıkarabilir.</p>\n<h2 id=\"avif-for-work\">İş için AVIF görselleri</h2>\n<p>İş arkadaşınıza görsel gönderirken JPG kullanın. Alıcının programı bilinmiyorsa JPG her zaman açılır.</p>\n<p>AVIF'i olduğu gibi göndermeyin. Alıcı dosyayı açamazsa iş gecikir.</p>\n<p>Dönüştürmeden önce kaliteyi kontrol edin. İş görsellerinde bulanıklık profesyonel görünmez.</p>\n<h2 id=\"avif-for-printing\">Baskı için AVIF görselleri</h2>\n<p>Baskı merkezleri AVIF kabul etmez. Baskıya göndermeden önce JPG'ye dönüştürün ve çözünürlüğü kontrol edin.</p>\n<p>Baskıda çözünürlük kritiktir. İnternetten indirilen küçük bir görsel baskıda bulanık görünür; 300 DPI hedefleyin.</p>\n<p>Baskı merkezine hangi formatı ve çözünürlüğü istediklerini sorun. Bu, boşa giden baskıyı önler.</p>\n<h2 id=\"avif-for-social-media\">Sosyal medya için AVIF görselleri</h2>\n<p>Sosyal platformlar yüklenen görseli genellikle kendi formatına çevirir. Yine de AVIF yüklemek sorun çıkarabilir.</p>\n<p>Paylaşmadan önce JPG'ye dönüştürün. Platform ne olursa olsun, JPG dosyası kabul edilir.</p>\n<p>Platformun istediği boyuta dikkat edin. Yanlış boyut kırpılır; format burada ikinci plandadır.</p>\n<h2 id=\"keeping-avif-originals\">Dönüştürdükten sonra AVIF orijinallerini saklamak</h2>\n<p>Orijinal AVIF'leri saklayın. JPG'den AVIF geri üretilemez; en kaliteli sürüm orijinaldir.</p>\n<p>Arşiv klasöründe AVIF'leri, kullanım klasöründe JPG'leri tutun. İki klasör birbirine karışmamalıdır.</p>\n<p>Depolama ucuzdur; kaybolan dosya pahalıdır. Orijinalleri silmek, ileride pişmanlık demektir.</p>\n<p>Özetle: web için AVIF, her yer için JPG. Karşılaştırma için <a href=\"/tr/blog/avif-vs-jpg\">AVIF ve JPG karşılaştırmasına</a> bakın; adımlar için <a href=\"/tr/blog/avif-jpg-ye-nasil-donusturulur\">AVIF JPG'ye nasıl dönüştürülür</a> yazısını okuyun. Dönüştürmek için <a href=\"/tr/avif-jpg-ye-donustur\">AVIF'den JPG'ye aracını</a> açın; genel dönüştürmeler için <a href=\"/tr/gorsel-donustur\">görsel dönüştürücü</a> de elinizin altındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"AVIF nedir ve bazı uygulamalar neden onu açamıyor?","answer":"AVIF, AV1 video codec'ine dayanan yeni bir görsel formatıdır; JPG'den yüzde 30-50 daha küçük dosyalar üretir. Yeni olduğu için birçok uygulama, form ve eski işletim sistemi onu henüz tanımıyor. Modern tarayıcılar destekler ama tarayıcı dışındaki sistemler geride kalıyor."},{"question":"Hangi tarayıcılar dönüştürme için AVIF çözebilir?","answer":"Chrome, Firefox, Safari ve Edge'in güncel sürümleri AVIF çözebilir. Dönüştürücü, tarayıcının çözücüsünü kullanır; tarayıcı AVIF açabiliyorsa dönüştürme çalışır. Eski bir tarayıcı kullanıyorsanız güncelleyin."},{"question":"AVIF'i JPG'ye dönüştürmek kalite kaybettirir mi?","answer":"Biraz, çünkü JPG daha kayıplı bir formattır. Ancak yüzde 85 kaliteyle kayıp gözle görülmez. HDR bilgisi kaybolur ama çoğu ekranda fark edilmez. Orijinal AVIF'i arşivde saklarsanız kalite kaybı yalnızca paylaşım kopyasında olur."},{"question":"AVIF'teki saydam alanlar JPG'de siyah mı olur?","answer":"Saydam alanlar, seçtiğiniz arka plan rengiyle dolar; varsayılan genellikle beyazdır. Siyah görüyorsanız arka plan rengini kontrol edin. Saydamlığı korumak istiyorsanız JPG yerine PNG'ye dönüştürün; PNG alfa kanalını korur."},{"question":"Kabul edilen en büyük AVIF dosyası nedir?","answer":"Araç 20 MB'a kadar dosyaları kabul eder. Çoğu AVIF bu sınırın çok altındadır, çünkü format çok verimlidir. Daha büyük bir dosyayla karşılaşırsanız önce boyutunu küçültün."},{"question":"JPG bazen neden AVIF'ten daha büyük oluyor?","answer":"Çünkü JPG daha eski ve daha az verimli bir formattır; aynı görseli daha fazla baytla saklar. Bir AVIF 200 KB ise JPG sürümü 400 KB olabilir. Bu fark normaldir ve uyumluluğun karşılığıdır: JPG her yerde açılır."}];
